def parse_row(line: str) -> list[str]:
    result = []
    current_field = []
    in_quotes = False
    quote_count = 0

    for char in line:
        if char == '"':
            if not in_quotes:
                in_quotes = True
                quote_count = 1
            else:
                if quote_count == 1:
                    in_quotes = False
                    quote_count = 0
        elif char == ',' and not in_quotes:
            result.append(''.join(current_field))
            current_field = []
        else:
            current_field.append(char)

    result.append(''.join(current_field))
    return result
