def dedupe(rows: list[dict], key: str) -> list[dict]:
    seen = set()
    result = []
    for row in rows:
        if key not in row:
            result.append(row)
        else:
            val = row[key]
            if val not in seen:
                seen.add(val)
                result.append(row)
    return result

