def parse_money(s: str) -> float | None:
    if not s:
        return None

    # Remove leading $ and strip whitespace
    cleaned = s.strip().lstrip('$')
    if not cleaned:
        return None

    # Handle invalid values like "n/a"
    if cleaned.lower() in {'n/a', 'na', 'null', 'none'}:
        return None

    # Remove thousands separators (commas)
    cleaned = cleaned.replace(',', '')

    # Try to parse as float
    try:
        return float(cleaned)
    except ValueError:
        return None
